18	  summary: string[]; // 3行の要約
19	  points: string[]; // 抽出した論点
20	  suggestedTags: string[];
21	  tags: string[];
22	  projectId: string | null;
23	  quoteCandidates: number;
24	  relatedNoteId?: string;
25	}
26	
27	export interface Project {
28	  id: string;
29	  name: string;
30	  /** The idea being developed in this project — free text. */
31	  description: string | null;
32	  tone: "accent" | "neutral";
33	  /** Number of sources filed under it. */
34	  count: number;
35	}
36	
37	export interface ProjectNoteRef {
38	  id: string;
39	  title: string;
40	  status: NoteStatus;
41	  updatedLabel: string;
42	}
43	
44	/** GET /api/projects/:id — the project workspace. */
45	export interface ProjectDetail extends Project {
46	  sources: Item[];
47	  notes: ProjectNoteRef[];
48	}
49	
50	export interface Tag {
51	  id: string;
52	  label: string;
53	  tone: "accent" | "neutral";
54	  count: number;
55	}
56	
57	export type NoteStatus = "draft" | "done";
58	
59	/**
60	 * Legacy hand-rolled block model. New notes store a Quill Delta in `Note.body`;
