1	import { and, eq, isNull, sql } from "drizzle-orm";
2	import {
3	  rewriteForExport,
4	  summariseMemo,
5	  summariseSource,
6	  synthesiseCompare,
7	} from "@/lib/ai";
8	import { fetchAndExtract } from "@/lib/extract";
9	import {
10	  type DeltaOp,
11	  deltaToMarkdown,
12	  deltaToPlainText,
13	  isDelta,
14	  legacyBlocksToDelta,
15	} from "@/lib/note-delta";
16	import type {
17	  CompareBoard,
18	  ExportDraft,
19	  ExportFormat,
20	  Item,
21	  Note,
22	  NoteSuggestion,
23	  Project,
24	  ProjectDetail,
25	  SourceKind,
26	  Tag,
27	} from "@/lib/types";
28	import { db, schema } from "./index";
29	
30	// ─────────────────────────────────────────────────────────────
31	// Every function here is scoped by the caller's internal `users.id` (see
32	// lib/db/current-user.ts). This is the real replacement for lib/store.ts —
33	// same function names and return shapes, backed by Postgres instead of a
34	// mutable object on globalThis. The Drizzle schema is the shared `@repo/db`
35	// package (camelCase columns, `Date` timestamps).
36	// ─────────────────────────────────────────────────────────────
37	
38	const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
39	/** Guard lookups: an empty or malformed id must not reach Postgres as a
40	 * `::uuid` cast (it throws instead of returning no rows). */
41	const isUuid = (id: string): boolean => UUID_RE.test(id);
42	
43	function relativeLabel(when: Date | string): string {
44	  const min = Math.floor((Date.now() - new Date(when).getTime()) / 60_000);
45	  if (min < 1) return "たった今";
46	  if (min < 60) return `${min}分前`;
47	  const hours = Math.floor(min / 60);
48	  if (hours < 24) return "今日";
49	  const days = Math.floor(hours / 24);
50	  return days === 1 ? "昨日" : `${days}日前`;
51	}
52	
53	function kindFromUrl(url: string): SourceKind {
54	  const u = url.toLowerCase();
55	  if (u.includes("youtube") || u.includes("youtu.be") || u.includes("vimeo")) return "video";
56	  if (u.endsWith(".pdf") || u.includes("arxiv.org")) return "pdf";
57	  if (u.includes("twitter.com") || u.includes("x.com") || u.includes("bsky")) return "thread";
58	  return "article";
59	}
60	
61	function siteFromUrl(url: string): string {
62	  try {
63	    return new URL(url).hostname.replace(/^www\./, "");
64	  } catch {
65	    return url.slice(0, 40);
66	  }
67	}
68	
69	function normalizeUrl(url: string): string {
70	  try {
71	    const u = new URL(url);
72	    return `${u.hostname.replace(/^www\./, "")}${u.pathname.replace(/\/+$/, "")}${u.search}`.toLowerCase();
73	  } catch {
74	    return url.trim().toLowerCase();
75	  }
76	}
77	
78	// ── Items ──────────────────────────────────────────────────
79	type SavedUrlRow = typeof schema.savedUrls.$inferSelect;
80	
81	function toItem(row: SavedUrlRow): Item {
82	  const site = row.kind === "note" ? (row.domain ?? "メモ") : (row.domain ?? siteFromUrl(row.url));
83	  return {
84	    id: row.id,
85	    url: row.url,
86	    kind: row.kind as SourceKind,
87	    site,
88	    title: row.title ?? site,
89	    addedAt: new Date(row.createdAt).toISOString(),
90	    addedLabel: relativeLabel(row.createdAt),
91	    status:
92	      row.fetchStatus === "success" ? "ready" : row.fetchStatus === "error" ? "ready" : "reading",
93	    durationLabel: row.durationLabel ?? undefined,
94	    summary: row.summaryLines,
95	    points: row.points,
96	    suggestedTags: row.suggestedTags,
97	    tags: row.tags,
98	    projectId: row.projectId ?? null,
99	    quoteCandidates: row.quoteCandidates,
100	    relatedNoteId: row.relatedNoteId ?? undefined,
101	  };
102	}
103	
104	export async function listItems(userId: string): Promise<Item[]> {
105	  const rows = await db.query.savedUrls.findMany({
106	    where: (t, { eq }) => eq(t.userId, userId),
107	    orderBy: (t, { desc }) => [desc(t.createdAt)],
108	  });
109	  return rows.map(toItem);
110	}
111	
112	/**
113	 * GET /api/items/importable — the "Hazyから追加" picker in the capture flow.
114	 * Every URL the user has in the hazy database (the `saved_urls` table this
115	 * app is connected to), newest first, so they can pull one into the note
116	 * pipeline (`/capture?id=…` → finishReading → 要約とタグ → 置き場所).
117	 *
118	 * Pasted memos (`kind: "note"`) are excluded — this is for real URLs. Items
119	 * hazy-note has already worked on (summary generated, or filed into a
120	 * project) are still listed; the picker marks them so and selecting one just
121	 * re-opens it. Unworked items sort to the top.
122	 */
123	export async function listImportable(userId: string): Promise<Item[]> {
124	  const rows = await db.query.savedUrls.findMany({
125	    where: (t, { and, eq, ne }) => and(eq(t.userId, userId), ne(t.kind, "note")),
126	    orderBy: (t, { desc }) => [desc(t.createdAt)],
127	  });
128	  const items = rows.map(toItem);
129	  const worked = (it: Item) => it.summary.length > 0 || it.projectId !== null;
130	  return [...items.filter((it) => !worked(it)), ...items.filter(worked)];
131	}
132	
133	export async function getItem(userId: string, id: string): Promise<Item | undefined> {
134	  if (!isUuid(id)) return undefined;
135	  const row = await db.query.savedUrls.findFirst({
136	    where: (t, { and, eq }) => and(eq(t.id, id), eq(t.userId, userId)),
137	  });
138	  return row ? toItem(row) : undefined;
139	}
140	
141	export async function addItem(userId: string, url: string): Promise<Item> {
142	  const site = siteFromUrl(url);
143	  const [row] = await db
144	    .insert(schema.savedUrls)
145	    .values({
146	      userId,
147	      url,
148	      normalizedUrl: normalizeUrl(url),
149	      domain: site,
150	      title: site,
151	      kind: kindFromUrl(url),
152	      fetchStatus: "pending",
153	    })
154	    .onConflictDoUpdate({
155	      target: [schema.savedUrls.userId, schema.savedUrls.normalizedUrl],
156	      set: { fetchStatus: "pending", updatedAt: new Date() },
157	    })
158	    .returning();
159	  const item = await getItem(userId, row.id);
160	  if (!item) throw new Error("item vanished immediately after write");
161	  return item;
162	}
163	
164	/**
165	 * POST /api/items — the memo path. A pasted memo becomes an item with no
166	 * external URL; `kind: "note"` and the raw text lives in `extracted_text`.
167	 */
168	export async function addMemo(userId: string, text: string): Promise<Item> {
169	  const token = `hazy:memo:${crypto.randomUUID()}`;
170	  const firstLine = text.trim().split("\n")[0].trim();
171	  const title = firstLine.length > 60 ? `${firstLine.slice(0, 60)}…` : firstLine || "メモ";
172	  const [row] = await db
173	    .insert(schema.savedUrls)
174	    .values({
175	      userId,
176	      url: token,
177	      normalizedUrl: token,
178	      domain: "メモ",
179	      title,
180	      kind: "note",
181	      extractedText: text,
182	      fetchStatus: "pending",
183	    })
184	    .returning();
185	  const item = await getItem(userId, row.id);
186	  if (!item) throw new Error("item vanished immediately after write");
187	  return item;
188	}
189	
190	/**
191	 * POST /api/items/:id/read — the "読み取り" step. For a URL this fetches the
192	 * page, extracts its text, and asks the model for a summary + tags. For a
193	 * pasted memo it just distils what was written. Best-effort: a fetch or AI
194	 * failure still resolves the item (fetch_status "error") instead of throwing.
195	 *
196	 * "Hazyから追加" fast path: an item saved via the hazy app already has its
197	 * page text in `extracted_text`. If it's substantial, summarise straight from
198	 * that — no second network fetch, and a transient fetch failure can't downgrade
199	 * an item hazy already read successfully.
200	 */
201	export async function finishReading(userId: string, id: string): Promise<Item | undefined> {
202	  const existing = await db.query.savedUrls.findFirst({
203	    where: (t, { and, eq }) => and(eq(t.id, id), eq(t.userId, userId)),
204	  });
205	  if (!existing) return undefined;
206	
207	  if (existing.kind !== "note" && (existing.extractedText?.trim().length ?? 0) >= 400) {
208	    const title =
209	      existing.title && existing.title !== existing.domain
210	        ? existing.title
211	        : (existing.domain ?? siteFromUrl(existing.url));
212	    const digest = await summariseSource({
213	      title,
214	      text: existing.extractedText ?? "",
215	      kind: existing.kind,
216	    });
217	    await db
218	      .update(schema.savedUrls)
219	      .set({
220	        fetchStatus: "success",
221	        title: digest.title?.trim() || title,
222	        durationLabel:
223	          existing.durationLabel ??
224	          (existing.estimatedReadMinutes ? `読了${existing.estimatedReadMinutes}分` : null),
225	        summaryLines: digest.summary,
226	        points: digest.points,
227	        suggestedTags: digest.suggestedTags,
228	        updatedAt: new Date(),
229	      })
230	      .where(eq(schema.savedUrls.id, id));
231	    return getItem(userId, id);
232	  }
233	
234	  if (existing.kind === "note") {
235	    const digest = await summariseMemo(existing.extractedText ?? "");
236	    await db
237	      .update(schema.savedUrls)
238	      .set({
239	        fetchStatus: "success",
240	        summaryLines: digest.summary,
241	        points: digest.points,
242	        suggestedTags: digest.suggestedTags,
243	        updatedAt: new Date(),
244	      })
245	      .where(eq(schema.savedUrls.id, id));
246	    return getItem(userId, id);
247	  }
248	
249	  let extracted: Awaited<ReturnType<typeof fetchAndExtract>>;
250	  try {
251	    extracted = await fetchAndExtract(existing.url);
252	  } catch (e) {
253	    await db
254	      .update(schema.savedUrls)
255	      .set({
256	        fetchStatus: "error",
257	        fetchError: (e as Error).message.slice(0, 500),
258	        updatedAt: new Date(),
259	      })
260	      .where(eq(schema.savedUrls.id, id));
261	    return getItem(userId, id);
262	  }
263	
264	  const title =
265	    extracted.title?.trim() ||
266	    (existing.title && existing.title !== existing.domain
267	      ? existing.title
268	      : (existing.domain ?? siteFromUrl(existing.url)));
269	
270	  const digest = await summariseSource({
271	    title,
272	    text: extracted.text,
273	    kind: existing.kind,
274	  });
275	
276	  await db
277	    .update(schema.savedUrls)
278	    .set({
279	      fetchStatus: "success",
280	      title: digest.title?.trim() || title,
281	      description: extracted.description ?? existing.description,
282	      faviconUrl: extracted.favicon ?? existing.faviconUrl,
283	      ogImageUrl: extracted.ogImage ?? existing.ogImageUrl,
284	      extractedText: extracted.text || existing.extractedText,
285	      contentLanguage: extracted.lang ?? existing.contentLanguage,
286	      estimatedReadMinutes: extracted.readMinutes ?? existing.estimatedReadMinutes,
287	      durationLabel:
288	        existing.durationLabel ?? (extracted.readMinutes ? `読了${extracted.readMinutes}分` : null),
289	      summaryLines: digest.summary,
290	      points: digest.points,
291	      suggestedTags: digest.suggestedTags,
292	      updatedAt: new Date(),
293	    })
294	    .where(eq(schema.savedUrls.id, id));
295	  return getItem(userId, id);
296	}
297	
298	export async function updateItem(
299	  userId: string,
300	  id: string,
301	  patch: Partial<Pick<Item, "tags" | "projectId" | "title" | "summary">>
302	): Promise<Item | undefined> {
303	  const existing = await getItem(userId, id);
304	  if (!existing) return undefined;
305	
306	  const colPatch: Partial<typeof schema.savedUrls.$inferInsert> = {};
307	  if (patch.tags) colPatch.tags = patch.tags;
308	  if (patch.title !== undefined) colPatch.title = patch.title;
309	  if (patch.summary) colPatch.summaryLines = patch.summary;
310	  if (Object.keys(colPatch).length) {
311	    colPatch.updatedAt = new Date();
312	    await db.update(schema.savedUrls).set(colPatch).where(eq(schema.savedUrls.id, id));
313	  }
314	
315	  if ("projectId" in patch) {
316	    await db
317	      .update(schema.savedUrls)
318	      .set({ projectId: patch.projectId || null, updatedAt: new Date() })
319	      .where(eq(schema.savedUrls.id, id));
320	  }
321	
322	  return getItem(userId, id);
323	}
324	
325	export async function deleteItem(userId: string, id: string): Promise<boolean> {
326	  const deleted = await db
327	    .delete(schema.savedUrls)
328	    .where(and(eq(schema.savedUrls.id, id), eq(schema.savedUrls.userId, userId)))
329	    .returning({ id: schema.savedUrls.id });
330	  return deleted.length > 0;
331	}
332	
333	// ── Projects & Tags ───────────────────────────────────────────
334	// A "project" (hazy-note's own `projects` table — separate from hazy's
335	// `collections`) is a space the user creates deliberately to develop an idea:
336	// `description`, the sources filed under it (`saved_urls.project_id`) and the
337	// notes under it (`notes.project_id`). `tone` is just a colour.
338	
339	function toProjectRow(r: {
340	  id: string;
341	  name: string;
342	  description: string | null;
343	  tone: string;
344	  count: number;
345	}): Project {
346	  return {
347	    id: r.id,
348	    name: r.name,
349	    description: r.description,
350	    tone: r.tone === "accent" ? "accent" : "neutral",
351	    count: r.count,
352	  };
353	}
354	
355	export async function listProjects(userId: string): Promise<Project[]> {
356	  const rows = await db
357	    .select({
358	      id: schema.projects.id,
359	      name: schema.projects.name,
360	      description: schema.projects.description,
361	      tone: schema.projects.tone,
362	      count: sql<number>`count(${schema.savedUrls.id})::int`,
363	    })
364	    .from(schema.projects)
365	    .leftJoin(schema.savedUrls, eq(schema.savedUrls.projectId, schema.projects.id))
366	    .where(eq(schema.projects.userId, userId))
367	    .groupBy(schema.projects.id)
368	    .orderBy(schema.projects.createdAt);
369	  return rows.map(toProjectRow);
370	}
371	
372	/** GET /api/projects/:id — the project workspace: its idea, sources and notes. */
373	export async function getProject(
374	  userId: string,
375	  id: string
376	): Promise<ProjectDetail | undefined> {
377	  if (!isUuid(id)) return undefined;
378	  const project = (await listProjects(userId)).find((p) => p.id === id);
379	  if (!project) return undefined;
380	
381	  const sourceRows = await db.query.savedUrls.findMany({
382	    where: (t, { and, eq }) => and(eq(t.userId, userId), eq(t.projectId, id)),
383	    orderBy: (t, { desc }) => [desc(t.createdAt)],
384	  });
385	  const sources = sourceRows.map(toItem);
386	
387	  const noteRows = await db.query.notes.findMany({
388	    where: (t, { and, eq }) => and(eq(t.userId, userId), eq(t.projectId, id)),
389	    orderBy: (t, { desc }) => [desc(t.updatedAt)],
390	  });
391	  const notes = noteRows.map((n) => ({
392	    id: n.id,
393	    title: n.title,
394	    status: n.status,
395	    updatedLabel: relativeLabel(n.updatedAt),
396	  }));
397	
398	  return { ...project, sources, notes };
399	}
400	
401	export async function createProject(
402	  userId: string,
403	  name: string,
404	  opts: { tone?: "accent" | "neutral"; description?: string } = {}
405	): Promise<Project> {
406	  const [row] = await db
407	    .insert(schema.projects)
408	    .values({
409	      userId,
410	      name: name.trim() || "無題のプロジェクト",
411	      tone: opts.tone ?? "neutral",
412	      description: opts.description?.trim() || null,
413	    })
414	    .returning();
415	  return toProjectRow({ ...row, count: 0 });
416	}
417	
418	export async function updateProject(
419	  userId: string,
420	  id: string,
421	  patch: { name?: string; description?: string | null; tone?: "accent" | "neutral" }
422	): Promise<Project | undefined> {
423	  const set: Partial<typeof schema.projects.$inferInsert> = {};
424	  if (patch.name !== undefined) set.name = patch.name.trim() || "無題のプロジェクト";
425	  if (patch.description !== undefined) set.description = patch.description?.trim() || null;
426	  if (patch.tone !== undefined) set.tone = patch.tone;
427	  if (Object.keys(set).length) {
428	    set.updatedAt = new Date();
429	    await db
430	      .update(schema.projects)
431	      .set(set)
432	      .where(and(eq(schema.projects.id, id), eq(schema.projects.userId, userId)));
433	  }
434	  return (await listProjects(userId)).find((p) => p.id === id);
435	}
436	
437	export async function deleteProject(userId: string, id: string): Promise<boolean> {
438	  const deleted = await db
439	    .delete(schema.projects)
440	    .where(and(eq(schema.projects.id, id), eq(schema.projects.userId, userId)))
441	    .returning({ id: schema.projects.id });
442	  return deleted.length > 0;
443	}
444	
445	export async function listTags(userId: string): Promise<Tag[]> {
446	  const res: unknown = await db.execute(sql`
447	    select label, count(*)::int as n
448	    from saved_urls, unnest(tags) as label
449	    where user_id = ${userId}
450	    group by label
451	    order by n desc, label
452	  `);
453	  // postgres.js returns an array; neon-http returns { rows }.
454	  const rows = (Array.isArray(res) ? res : (res as { rows: unknown[] }).rows) as {
455	    label: string;
456	    n: number;
457	  }[];
458	  return rows.map((r) => ({
459	    id: `t-${encodeURIComponent(r.label)}`,
460	    label: r.label,
461	    tone: "neutral",
462	    count: r.n,
463	  }));
464	}
465	
466	// ── Notes ──────────────────────────────────────────────────
467	function toNote(row: typeof schema.notes.$inferSelect): Note {
468	  // Notes written before the Quill editor only have `blocks`; convert on read
469	  // (persisted back to `body` / `suggestions` on the next save).
470	  const rowBody = row.body as DeltaOp[];
471	  const rowSug = row.suggestions as NoteSuggestion[];
472	  const hasBody = isDelta(rowBody) && rowBody.length > 0;
473	  const hasSug = rowSug.length > 0;
474	  const legacy = hasBody && hasSug ? null : legacyBlocksToDelta(row.blocks);
475	  return {
476	    id: row.id,
477	    title: row.title,
478	    projectId: row.projectId ?? "",
479	    tags: row.tags as Note["tags"],
480	    status: row.status,
481	    updatedLabel: `自動保存 · ${relativeLabel(row.updatedAt)}`,
482	    body: hasBody ? rowBody : (legacy?.body ?? []),
483	    suggestions: hasSug ? rowSug : (legacy?.suggestions ?? []),
484	    sources: row.sources as Note["sources"],
485	    links: row.links as Note["links"],
486	    flags: row.flags as Note["flags"],
487	  };
488	}
489	
490	export async function listNotes(userId: string): Promise<Note[]> {
491	  const rows = await db.query.notes.findMany({
492	    where: (t, { eq }) => eq(t.userId, userId),
493	    orderBy: (t, { desc }) => [desc(t.updatedAt)],
494	  });
495	  return rows.map(toNote);
496	}
497	
498	/**
499	 * Create a note. The client only calls this once a `/notes/new` draft has
500	 * actual content (a paragraph, a title change, a tag…), so `blocks` / `tags` /
501	 * `status` may already carry that first edit.
502	 */
503	export async function createNote(
504	  userId: string,
505	  input: {
506	    title?: string;
507	    projectId?: string | null;
508	    text?: string;
509	    body?: DeltaOp[];
510	    suggestions?: NoteSuggestion[];
511	    tags?: Note["tags"];
512	    status?: Note["status"];
513	    sources?: Note["sources"];
514	  } = {}
515	): Promise<Note> {
516	  const body: DeltaOp[] =
517	    input.body ?? (input.text?.trim() ? [{ insert: `${input.text.trim()}\n` }] : []);
518	  const [row] = await db
519	    .insert(schema.notes)
520	    .values({
521	      userId,
522	      projectId: input.projectId || null,
523	      title: input.title?.trim() || "無題のノート",
524	      status: input.status ?? "draft",
525	      tags: input.tags ?? [],
526	      blocks: [],
527	      body,
528	      suggestions: input.suggestions ?? [],
529	      sources: input.sources ?? [],
530	      links: [],
531	      flags: [],
532	    })
533	    .returning();
534	  return toNote(row);
535	}
536	
537	export async function updateNote(
538	  userId: string,
539	  id: string,
540	  patch: Partial<
541	    Pick<Note, "title" | "status" | "projectId" | "body" | "suggestions" | "tags" | "sources">
542	  >
543	): Promise<Note | undefined> {
544	  const row = await getNoteRow(userId, id);
545	  if (!row) return undefined;
546	  const set: Partial<typeof schema.notes.$inferInsert> = {
547	    updatedAt: new Date(),
548	  };
549	  if (patch.title !== undefined) set.title = patch.title.trim() || "無題のノート";
550	  if (patch.status !== undefined) set.status = patch.status;
551	  if (patch.projectId !== undefined) set.projectId = patch.projectId || null;
552	  if (patch.body !== undefined) set.body = patch.body;
553	  if (patch.suggestions !== undefined) set.suggestions = patch.suggestions;
554	  if (patch.tags !== undefined) set.tags = patch.tags;
555	  if (patch.sources !== undefined) set.sources = patch.sources;
556	  await db.update(schema.notes).set(set).where(eq(schema.notes.id, id));
557	  return getNote(userId, id);
558	}
559	
560	export async function deleteNote(userId: string, id: string): Promise<boolean> {
561	  const deleted = await db
562	    .delete(schema.notes)
563	    .where(and(eq(schema.notes.id, id), eq(schema.notes.userId, userId)))
564	    .returning({ id: schema.notes.id });
565	  return deleted.length > 0;
566	}
567	
568	export async function getNote(userId: string, id: string): Promise<Note | undefined> {
569	  if (!isUuid(id)) return undefined;
570	  const row = await db.query.notes.findFirst({
571	    where: (t, { and, eq }) => and(eq(t.id, id), eq(t.userId, userId)),
572	  });
573	  return row ? toNote(row) : undefined;
574	}
575	
576	async function getNoteRow(userId: string, id: string) {
577	  if (!isUuid(id)) return undefined;
578	  return db.query.notes.findFirst({
579	    where: (t, { and, eq }) => and(eq(t.id, id), eq(t.userId, userId)),
580	  });
581	}
582	
583	/**
584	 * Accept a sidebar suggestion: the client has already inserted its text into
585	 * the Quill body (and that save is in flight), so here we just drop it from the
586	 * list and clear any "未着手 / 未執筆 / 下書き" flag.
587	 */
588	export async function acceptSuggestion(
589	  userId: string,
590	  noteId: string,
591	  suggestionId: string
592	): Promise<Note | undefined> {
593	  const row = await getNoteRow(userId, noteId);
594	  if (!row) return undefined;
595	  const current = toNote(row).suggestions;
596	  if (!current.some((s) => s.id === suggestionId)) return toNote(row);
597	  const suggestions = current.filter((s) => s.id !== suggestionId);
598	  const flags = (row.flags as Note["flags"]).filter(
599	    (f) => !/未着手|未執筆|下書き|未完/.test(f.text)
600	  );
601	  await db
602	    .update(schema.notes)
603	    .set({ suggestions, flags, updatedAt: new Date() })
604	    .where(eq(schema.notes.id, noteId));
605	  return getNote(userId, noteId);
606	}
607	
608	export async function dismissSuggestion(
609	  userId: string,
610	  noteId: string,
611	  suggestionId: string
612	): Promise<Note | undefined> {
613	  const row = await getNoteRow(userId, noteId);
614	  if (!row) return undefined;
615	  const suggestions = toNote(row).suggestions.filter((s) => s.id !== suggestionId);
616	  await db
617	    .update(schema.notes)
618	    .set({ suggestions, updatedAt: new Date() })
619	    .where(eq(schema.notes.id, noteId));
620	  return getNote(userId, noteId);
621	}
622	
623	export async function appendParagraph(
624	  userId: string,
625	  noteId: string,
626	  text: string
627	): Promise<Note | undefined> {
628	  const row = await getNoteRow(userId, noteId);
629	  if (!row) return undefined;
630	  const body = [...toNote(row).body];
631	  body.push({ insert: body.length ? `\n${text}\n` : `${text}\n` });
632	  await db
633	    .update(schema.notes)
634	    .set({ body, updatedAt: new Date() })
635	    .where(eq(schema.notes.id, noteId));
636	  return getNote(userId, noteId);
637	}
638	
639	// ── Compare ────────────────────────────────────────────────
640	function toCompare(row: typeof schema.compareBoards.$inferSelect): CompareBoard {
641	  return {
642	    id: row.id,
643	    projectId: row.projectId ?? "",
644	    sources: row.sources,
645	    axes: row.axes as CompareBoard["axes"],
646	    summary: row.summary,
647	    candidateAxes: row.candidateAxes,
648	  };
649	}
650	
651	export async function getCompare(userId: string): Promise<CompareBoard | undefined> {
652	  const row = await db.query.compareBoards.findFirst({
653	    where: (t, { eq }) => eq(t.userId, userId),
654	    orderBy: (t, { desc }) => [desc(t.updatedAt)],
655	  });
656	  return row ? toCompare(row) : undefined;
657	}
658	
659	/**
660	 * "差分をまとめる" — (re)build the compare board from the ready sources in a
661	 * project (or, with no project, every ready source). Needs ≥2 sources.
662	 */
663	export async function buildCompareBoard(userId: string, projectId?: string): Promise<CompareBoard> {
664	  const rows = await db.query.savedUrls.findMany({
665	    where: (t, { and, eq }) => and(eq(t.userId, userId), eq(t.fetchStatus, "success")),
666	    orderBy: (t, { desc }) => [desc(t.createdAt)],
667	  });
668	  const items = rows
669	    .map(toItem)
670	    .filter((it) => (projectId ? it.projectId === projectId : true))
671	    .filter((it) => it.summary.length > 0)
672	    .slice(0, 8);
673	
674	  const synth = await synthesiseCompare(
675	    items.map((it) => ({ title: it.title, summary: it.summary }))
676	  );
677	
678	  await db
679	    .delete(schema.compareBoards)
680	    .where(
681	      and(
682	        eq(schema.compareBoards.userId, userId),
683	        projectId
684	          ? eq(schema.compareBoards.projectId, projectId)
685	          : isNull(schema.compareBoards.projectId)
686	      )
687	    );
688	  const [row] = await db
689	    .insert(schema.compareBoards)
690	    .values({
691	      userId,
692	      projectId: projectId ?? null,
693	      sources: items.map((it) => it.title),
694	      axes: synth.axes,
695	      summary: synth.summary,
696	      candidateAxes: synth.candidateAxes,
697	    })
698	    .returning();
699	  return toCompare(row);
700	}
701	
702	// ── Export ─────────────────────────────────────────────────
703	function countChars(blocks: { text?: string }[]): number {
704	  return blocks.reduce((n, b) => n + (b.text?.length ?? 0), 0);
705	}
706	
707	export async function buildExport(
708	  userId: string,
709	  noteId: string,
710	  format: ExportFormat = "blog"
711	): Promise<ExportDraft> {
712	  let note = await getNote(userId, noteId);
713	  if (!note) {
714	    const fallback = await db.query.notes.findFirst({
715	      where: (t, { eq }) => eq(t.userId, userId),
716	      orderBy: (t, { desc }) => [desc(t.updatedAt)],
717	    });
718	    note = fallback ? toNote(fallback) : undefined;
719	  }
720	  if (!note) {
721	    return {
722	      format,
723	      meta: "ノートがありません",
724	      title: "書き出すノートがありません",
725	      blocks: [{ type: "p", text: "先にノートを作成してください。" }],
726	      provenance: [],
727	    };
728	  }
729	
730	  const draft = await rewriteForExport({
731	    title: note.title,
732	    markdown: deltaToMarkdown(note.body),
733	    format,
734	  });
735	  const chars = countChars(draft.blocks);
736	  const minutes = Math.max(1, Math.round(chars / 500));
737	  const meta =
738	    format === "bullets"
739	      ? `${draft.blocks.filter((b) => b.type === "p").length}項目`
740	      : `約${chars.toLocaleString()}字 · 読了${minutes}分`;
741	
742	  return { format, meta, ...draft };
743	}
