3	import Link from "next/link";
4	import { useRouter } from "next/navigation";
5	import { useCallback, useEffect, useRef, useState } from "react";
6	import { Icon } from "@/components/icon";
7	import { Loading, Spinner } from "@/components/loading";
8	import { NoteEditor, type CiteTarget, type NoteEditorHandle } from "@/components/note-editor";
9	import { Button } from "@/components/ui";
10	import { api } from "@/lib/api";
11	import type { DeltaOp } from "@/lib/note-delta";
12	import type { Note, Project } from "@/lib/types";
13	
14	const BLANK: Note = {
15	  id: "",
16	  title: "無題のノート",
17	  projectId: "",
18	  tags: [],
19	  status: "draft",
20	  updatedLabel: "まだ保存していません",
21	  body: [],
22	  suggestions: [],
23	  sources: [],
24	  links: [],
25	  flags: [],
26	};
27	
28	/** `id` is undefined for the `/notes/new` draft — nothing is written to the
29	 *  DB until the first real edit. */
30	export function NoteClient({ id }: { id?: string }) {
31	  const router = useRouter();
32	  const [noteId, setNoteId] = useState<string | undefined>(id);
33	  const [note, setNote] = useState<Note | null>(id ? null : BLANK);
34	  const [notFound, setNotFound] = useState(false);
35	  const [saving, setSaving] = useState(false);
36	  const [projects, setProjects] = useState<Project[]>([]);
37	  const isDraft = !noteId;
38	
39	  const editorRef = useRef<NoteEditorHandle>(null);
40	
41	  useEffect(() => {
42	    api.projects().then(setProjects).catch(() => {});
43	  }, []);
44	
45	  // The authoritative note / id, updated synchronously so rapid edits chain
46	  // correctly instead of building off a stale render.
47	  const noteRef = useRef<Note | null>(note);
48	  const idRef = useRef<string | undefined>(noteId);
49	  const chain = useRef<Promise<unknown>>(Promise.resolve());
50	  const adopt = (n: Note) => {
51	    noteRef.current = n;
52	    setNote(n);
53	  };
54	
55	  const load = useCallback(() => {
56	    if (!noteId) return;
57	    api
58	      .note(noteId)
59	      .then(adopt)
60	      .catch(() => setNotFound(true));
61	  }, [noteId]);
62	  useEffect(() => {
63	    load();
64	  }, [load]);
65	
66	  /** Append a write to the queue — never runs two at once, and a failure
67	   * doesn't stall the queue. */
68	  function enqueue(job: () => Promise<void>) {
69	    chain.current = chain.current
70	      .then(async () => {
71	        setSaving(true);
72	        try {
73	          await job();
74	        } finally {
75	          setSaving(false);
76	        }
77	      })
78	      .catch((e) => {
79	        console.error("note write failed", e);
80	        setSaving(false);
81	      });
82	  }
83	
84	  /**
85	   * Apply an edit. Local state changes immediately; the write is queued so
86	   * overlapping edits never race (each write replaces the whole note). On a
87	   * `/notes/new` draft the first edit creates the row — after that it's a PATCH
88	   * and the URL is swapped in place (no navigation, no lost focus).
89	   */
90	  function mutate(patch: Partial<Note>) {
91	    const base = noteRef.current;
92	    if (!base) return;
93	    adopt({ ...base, ...patch });
94	    enqueue(async () => {
95	      const cur = noteRef.current;
96	      if (!cur) return;
97	      const payload = {
98	        title: cur.title,
99	        body: cur.body,
100	        suggestions: cur.suggestions,
101	        tags: cur.tags,
102	        status: cur.status,
103	        sources: cur.sources,
104	        projectId: cur.projectId,
105	      };
106	      if (idRef.current) {
107	        const saved = await api.updateNote(idRef.current, payload);
108	        noteRef.current = { ...noteRef.current!, updatedLabel: saved.updatedLabel };
109	        setNote(noteRef.current);
110	      } else {
111	        const created = await api.addNote(payload);
112	        idRef.current = created.id;
113	        setNoteId(created.id);
114	        window.history.replaceState(null, "", `/notes/${created.id}`);
115	        noteRef.current = {
116	          ...noteRef.current!,
117	          id: created.id,
118	          updatedLabel: created.updatedLabel,
119	        };
120	        setNote(noteRef.current);
121	      }
122	    });
123	  }
124	
125	  const saveBody = (ops: DeltaOp[]) => mutate({ body: ops });
126	
127	  function act(suggestionId: string, action: "accept" | "dismiss") {
128	    if (!idRef.current) return; // suggestions only exist on saved notes
129	    enqueue(async () => {
130	      adopt(await api.suggestion(idRef.current as string, suggestionId, action));
131	    });
132	  }
133	
134	  /** Record an `@`-cited URL as a source of this note. */
135	  function cite(t: CiteTarget) {
136	    const base = noteRef.current;
137	    if (!base) return;
138	    const label = `${t.title} — ${t.site}`;
139	    if (base.sources.some((s) => s.url === t.url || s.label === label)) return;
140	    const n = base.sources.reduce((m, s) => Math.max(m, s.n), 0) + 1;
141	    mutate({ sources: [...base.sources, { n, label, cited: true, url: t.url }] });
142	  }
143	
144	  function addTag() {
145	    const b = noteRef.current;
146	    if (!b) return;
147	    const label = window.prompt("タグ")?.trim();
148	    if (!label || b.tags.some((t) => t.label === label)) return;
149	    mutate({ tags: [...b.tags, { label, tone: "neutral" }] });
150	  }
151	
152	  function removeTag(label: string) {
153	    const b = noteRef.current;
154	    if (!b) return;
155	    mutate({ tags: b.tags.filter((t) => t.label !== label) });
156	  }
157	
158	  function toggleStatus() {
159	    const b = noteRef.current;
160	    if (!b) return;
161	    mutate({ status: b.status === "done" ? "draft" : "done" });
162	  }
163	
164	  function renameNote() {
165	    const b = noteRef.current;
166	    if (!b) return;
167	    const title = window.prompt("ノートのタイトル", b.title);
168	    if (title == null || title === b.title) return;
169	    mutate({ title });
170	  }
171	
172	  async function removeNote() {
173	    if (isDraft) return router.push("/notes");
174	    if (!window.confirm("このノートを削除しますか？")) return;
175	    await api.deleteNote(idRef.current as string);
176	    router.push("/notes");
177	  }
178	
179	  if (notFound) return <div className="p-8 text-text/50">ノートが見つかりません。</div>;
180	  if (!note) return <Loading label="ノートを開いています" />;
181	
182	  return (
183	    <div className="grid min-h-screen grid-cols-1 lg:grid-cols-[1fr_260px]">
184	      <main className="flex flex-col gap-4 p-4 pb-8 sm:p-[28px_44px_34px]">
185	        <div className="flex flex-wrap items-center gap-[10px] text-[12px] text-text/45">
186	          <Icon name="notebook" />
187	          ノート
188	          <Icon name="caret-right" size={11} />
189	          <span className="text-text">{note.title}</span>
190	          <div className="flex flex-wrap items-center gap-[7px] sm:ml-auto">
191	            <span className="flex items-center gap-[5px] text-[11px]">
192	              {saving && <Spinner className="size-[11px] text-accent" />}
193	              {saving ? "保存中…" : note.updatedLabel}
194	            </span>
195	            <button
196	              type="button"
197	              onClick={renameNote}
198	              className="btn btn-ghost px-[9px] py-[5px] text-[12px]"
199	            >
200	              <Icon name="pencil-simple" /> 改名
201	            </button>
202	            <button
203	              type="button"
204	              onClick={removeNote}
205	              className="btn btn-ghost px-[9px] py-[5px] text-[12px] text-text/45"
206	            >
207	              <Icon name="trash" /> {isDraft ? "破棄" : "削除"}
208	            </button>
209	            {!isDraft && (
210	              <Link
211	                href={`/export?noteId=${note.id}`}
212	                className="btn btn-secondary px-[9px] py-[5px] text-[12px]"
213	              >
214	                <Icon name="export" /> 書き出す
215	              </Link>
216	            )}
217	          </div>
218	        </div>
219	
220	        <div className="flex items-center gap-[10px]">
221	          <h2 className="tracking-[-0.025em]">{note.title}</h2>
222	          <button
223	            type="button"
224	            onClick={toggleStatus}
225	            className={`tag ${note.status === "done" ? "tag-accent" : "tag-outline"}`}
226	            title="下書き / 完了 を切り替え"
227	          >
228	            <Icon name={note.status === "done" ? "check-circle" : "circle-dashed"} size={12} />
229	            {note.status === "done" ? "完了" : "下書き"}
230	          </button>
231	        </div>
232	
233	        <div className="flex flex-wrap items-center gap-[6px]">
234	          {note.tags.map((t) => (
235	            <button
236	              type="button"
237	              key={t.label}
238	              onClick={() => removeTag(t.label)}
239	              className={`tag ${t.tone === "accent" ? "tag-accent" : t.tone === "outline" ? "tag-outline" : "tag-neutral"} hover:line-through`}
240	              title="タグを外す"
241	            >
242	              {t.label}
243	              <Icon name="x" size={10} className="ml-[4px] opacity-60" />
244	            </button>
