"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useCallback, useEffect, useRef, useState } from "react";
import { Icon } from "@/components/icon";
import { Loading, Spinner } from "@/components/loading";
import { NoteEditor, type CiteTarget, type NoteEditorHandle } from "@/components/note-editor";
import { Button } from "@/components/ui";
import { api } from "@/lib/api";
import type { DeltaOp } from "@/lib/note-delta";
import type { Note, Project } from "@/lib/types";

const BLANK: Note = {
  id: "",
  title: "無題のノート",
  projectId: "",
  tags: [],
  status: "draft",
  updatedLabel: "まだ保存していません",
  body: [],
  suggestions: [],
  sources: [],
  links: [],
  flags: [],
};

/** `id` is undefined for the `/notes/new` draft — nothing is written to the
 *  DB until the first real edit. */
export function NoteClient({ id }: { id?: string }) {
  const router = useRouter();
  const [noteId, setNoteId] = useState<string | undefined>(id);
  const [note, setNote] = useState<Note | null>(id ? null : BLANK);
  const [notFound, setNotFound] = useState(false);
  const [saving, setSaving] = useState(false);
  const [projects, setProjects] = useState<Project[]>([]);
  const isDraft = !noteId;

  const editorRef = useRef<NoteEditorHandle>(null);

  useEffect(() => {
    api.projects().then(setProjects).catch(() => {});
  }, []);

  // The authoritative note / id, updated synchronously so rapid edits chain
  // correctly instead of building off a stale render.
  const noteRef = useRef<Note | null>(note);
  const idRef = useRef<string | undefined>(noteId);
  const chain = useRef<Promise<unknown>>(Promise.resolve());
  const adopt = (n: Note) => {
    noteRef.current = n;
    setNote(n);
  };

  const load = useCallback(() => {
    if (!noteId) return;
    api
      .note(noteId)
      .then(adopt)
      .catch(() => setNotFound(true));
  }, [noteId]);
  useEffect(() => {
    load();
  }, [load]);

  /** Append a write to the queue — never runs two at once, and a failure
   * doesn't stall the queue. */
  function enqueue(job: () => Promise<void>) {
    chain.current = chain.current
      .then(async () => {
        setSaving(true);
        try {
          await job();
        } finally {
          setSaving(false);
        }
      })
      .catch((e) => {
        console.error("note write failed", e);
        setSaving(false);
      });
  }

  /**
   * Apply an edit. Local state changes immediately; the write is queued so
   * overlapping edits never race (each write replaces the whole note). On a
   * `/notes/new` draft the first edit creates the row — after that it's a PATCH
   * and the URL is swapped in place (no navigation, no lost focus).
   */
  function mutate(patch: Partial<Note>) {
    const base = noteRef.current;
    if (!base) return;
    adopt({ ...base, ...patch });
    enqueue(async () => {
      const cur = noteRef.current;
      if (!cur) return;
      const payload = {
        title: cur.title,
        body: cur.body,
        suggestions: cur.suggestions,
        tags: cur.tags,
        status: cur.status,
        sources: cur.sources,
        projectId: cur.projectId,
      };
      if (idRef.current) {
        const saved = await api.updateNote(idRef.current, payload);
        noteRef.current = { ...noteRef.current!, updatedLabel: saved.updatedLabel };
        setNote(noteRef.current);
      } else {
        const created = await api.addNote(payload);
        idRef.current = created.id;
        setNoteId(created.id);
        window.history.replaceState(null, "", `/notes/${created.id}`);
        noteRef.current = {
          ...noteRef.current!,
          id: created.id,
          updatedLabel: created.updatedLabel,
        };
        setNote(noteRef.current);
      }
    });
  }

  const saveBody = (ops: DeltaOp[]) => mutate({ body: ops });

  function act(suggestionId: string, action: "accept" | "dismiss") {
    if (!idRef.current) return; // suggestions only exist on saved notes
    enqueue(async () => {
      adopt(await api.suggestion(idRef.current as string, suggestionId, action));
    });
  }

  /** Record an `@`-cited URL as a source of this note. */
  function cite(t: CiteTarget) {
    const base = noteRef.current;
    if (!base) return;
    const label = `${t.title} — ${t.site}`;
    if (base.sources.some((s) => s.url === t.url || s.label === label)) return;
    const n = base.sources.reduce((m, s) => Math.max(m, s.n), 0) + 1;
    mutate({ sources: [...base.sources, { n, label, cited: true, url: t.url }] });
  }

  function addTag() {
    const b = noteRef.current;
    if (!b) return;
    const label = window.prompt("タグ")?.trim();
    if (!label || b.tags.some((t) => t.label === label)) return;
    mutate({ tags: [...b.tags, { label, tone: "neutral" }] });
  }

  function removeTag(label: string) {
    const b = noteRef.current;
    if (!b) return;
    mutate({ tags: b.tags.filter((t) => t.label !== label) });
  }

  function toggleStatus() {
    const b = noteRef.current;
    if (!b) return;
    mutate({ status: b.status === "done" ? "draft" : "done" });
  }

  function renameNote() {
    const b = noteRef.current;
    if (!b) return;
    const title = window.prompt("ノートのタイトル", b.title);
    if (title == null || title === b.title) return;
    mutate({ title });
  }

  async function removeNote() {
    if (isDraft) return router.push("/notes");
    if (!window.confirm("このノートを削除しますか？")) return;
    await api.deleteNote(idRef.current as string);
    router.push("/notes");
  }

  if (notFound) return <div className="p-8 text-text/50">ノートが見つかりません。</div>;
  if (!note) return <Loading label="ノートを開いています" />;

  return (
    <div className="grid min-h-screen grid-cols-1 lg:grid-cols-[1fr_260px]">
      <main className="flex flex-col gap-4 p-4 pb-8 sm:p-[28px_44px_34px]">
        <div className="flex flex-wrap items-center gap-[10px] text-[12px] text-text/45">
          <Icon name="notebook" />
          ノート
          <Icon name="caret-right" size={11} />
          <span className="text-text">{note.title}</span>
          <div className="flex flex-wrap items-center gap-[7px] sm:ml-auto">
            <span className="flex items-center gap-[5px] text-[11px]">
              {saving && <Spinner className="size-[11px] text-accent" />}
              {saving ? "保存中…" : note.updatedLabel}
            </span>
            <button
              type="button"
              onClick={renameNote}
              className="btn btn-ghost px-[9px] py-[5px] text-[12px]"
            >
              <Icon name="pencil-simple" /> 改名
            </button>
            <button
              type="button"
              onClick={removeNote}
              className="btn btn-ghost px-[9px] py-[5px] text-[12px] text-text/45"
            >
              <Icon name="trash" /> {isDraft ? "破棄" : "削除"}
            </button>
            {!isDraft && (
              <Link
                href={`/export?noteId=${note.id}`}
                className="btn btn-secondary px-[9px] py-[5px] text-[12px]"
              >
                <Icon name="export" /> 書き出す
              </Link>
            )}
          </div>
        </div>

        <div className="flex items-center gap-[10px]">
          <h2 className="tracking-[-0.025em]">{note.title}</h2>
          <button
            type="button"
            onClick={toggleStatus}
            className={`tag ${note.status === "done" ? "tag-accent" : "tag-outline"}`}
            title="下書き / 完了 を切り替え"
          >
            <Icon name={note.status === "done" ? "check-circle" : "circle-dashed"} size={12} />
            {note.status === "done" ? "完了" : "下書き"}
          </button>
        </div>

        <div className="flex flex-wrap items-center gap-[6px]">
          {note.tags.map((t) => (
            <button
              type="button"
              key={t.label}
              onClick={() => removeTag(t.label)}
              className={`tag ${t.tone === "accent" ? "tag-accent" : t.tone === "outline" ? "tag-outline" : "tag-neutral"} hover:line-through`}
              title="タグを外す"
            >
              {t.label}
              <Icon name="x" size={10} className="ml-[4px] opacity-60" />
            </button>
          ))}
          <button type="button" onClick={addTag} className="tag tag-outline text-text/60">
            <Icon name="plus" size={10} className="mr-[3px]" /> タグ
          </button>
          <label className="ml-auto flex items-center gap-[6px] text-[12px] text-text/55">
            <Icon name="folder-open" size={13} className="text-accent" />
            <select
              className="input w-auto py-[3px] text-[12px]"
              value={note.projectId || ""}
              onChange={(e) => mutate({ projectId: e.target.value })}
            >
              <option value="">プロジェクトなし</option>
              {projects.map((p) => (
                <option key={p.id} value={p.id}>
                  {p.name}
                </option>
              ))}
            </select>
          </label>
        </div>

        <div className="max-w-[66ch]">
          <NoteEditor
            key={id ?? "draft"}
            ref={editorRef}
            value={note.body}
            onChange={saveBody}
            onCite={cite}
            placeholder="ここに書く…  選択でツールバー、@ でURLを引用"
          />
        </div>
      </main>

      <aside className="flex flex-col gap-[18px] bg-neutral-900 p-[18px_16px]">
        <Panel title="このノートの状態">
          {note.flags.length === 0 && <div className="text-[12px] text-text/40">特にありません</div>}
          {note.flags.map((f) => (
            <div key={f.text} className="flex items-center gap-2 text-[12.5px] opacity-90">
              <Icon
                name={f.icon}
                size={15}
                className={
                  f.tone === "accent"
                    ? "text-accent"
                    : f.tone === "accent-400"
                      ? "text-accent-400"
                      : "text-neutral-600"
                }
              />
              {f.text}
            </div>
          ))}
        </Panel>

        {note.suggestions.length > 0 && (
          <Panel title="AIの提案">
            {note.suggestions.map((s) => (
              <div
                key={s.id}
                className="flex flex-col gap-[9px] rounded-lg bg-accent/[0.07] px-3 py-[12px] shadow-[0_0_0_1px_var(--color-accent-800)]"
              >
                <div className="flex items-center gap-[6px] text-[10px] uppercase tracking-[0.08em] text-accent">
                  <Icon name="sparkle" size={12} />
                  {s.kind}
                </div>
                <p className="m-0 text-[13px] leading-[1.75] opacity-80">
                  {s.text}
                  {s.ref && <sup className="ml-[2px] text-[10px]">{s.ref}</sup>}
                </p>
                <div className="flex items-center gap-[6px]">
                  <Button
                    variant="primary"
                    className="text-[12px]"
                    onClick={() => {
                      editorRef.current?.insertTextAtCursor(s.text);
                      act(s.id, "accept");
                    }}
                  >
                    <Icon name="arrow-down-left" /> 本文に採る
                  </Button>
                  <button
                    type="button"
                    className="btn btn-ghost ml-auto text-[12px] text-text/45"
                    onClick={() => act(s.id, "dismiss")}
                  >
                    消す
                  </button>
                </div>
              </div>
            ))}
          </Panel>
        )}

        <Panel title="このノートの出典">
          {note.sources.length === 0 && (
            <div className="text-[12px] text-text/40">まだありません</div>
          )}
          {note.sources.map((s) => {
            const body = (
              <>
                <span className={s.cited ? "text-accent" : ""}>{s.n}</span>
                <span className="min-w-0 flex-1">{s.label}</span>
              </>
            );
            const cls = `flex gap-[7px] text-[12px] leading-[1.45] ${
              s.cited ? "opacity-75" : "opacity-50"
            }`;
            return s.url ? (
              <a
                key={s.n}
                href={s.url}
                target="_blank"
                rel="noreferrer"
                className={`${cls} no-underline hover:opacity-100 hover:underline`}
              >
                {body}
              </a>
            ) : (
              <div key={s.n} className={cls}>
                {body}
              </div>
            );
          })}
        </Panel>

        {note.links.length > 0 && (
          <Panel title="つながるノート">
            {note.links.map((l) => (
              <Link
                key={l.noteId}
                href={`/notes/${l.noteId}`}
                className="flex flex-col gap-[3px] rounded-lg bg-surface p-[10px] no-underline shadow-[0_0_0_1px_var(--color-neutral-900)]"
              >
                <span className="text-[12.5px] font-medium text-text">{l.title}</span>
                <span className="text-[11px] opacity-60">{l.reason}</span>
              </Link>
            ))}
          </Panel>
        )}

        <div className="mt-auto flex flex-col gap-2 rounded-[9px] bg-accent/[0.07] p-3 shadow-[0_0_0_1px_var(--color-accent-800)]">
          <div className="text-[12px] leading-[1.6]">
            {isDraft ? "書き始めると保存されます" : `${note.sources.length}出典`}
          </div>
          {!isDraft && (
            <Link
              href={`/export?noteId=${note.id}`}
              className="btn btn-primary self-start px-[9px] py-[5px] text-[12px]"
            >
              <Icon name="article" /> 下書きを起こす
            </Link>
          )}
        </div>
      </aside>
    </div>
  );
}

function Panel({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div className="flex flex-col gap-2">
      <div className="text-[10px] uppercase tracking-[0.09em] text-text/40">{title}</div>
      {children}
    </div>
  );
}

import type {
  CompareBoard,
  ExportDraft,
  ExportFormat,
  Item,
  Note,
  Project,
  ProjectDetail,
  Tag,
} from "./types";

async function j<T>(res: Response): Promise<T> {
  if (!res.ok) throw new Error(`${res.status} ${res.statusText}`);
  return res.json() as Promise<T>;
}

const opts = (method: string, body?: unknown): RequestInit => ({
  method,
  headers: body !== undefined ? { "content-type": "application/json" } : undefined,
  body: body !== undefined ? JSON.stringify(body) : undefined,
  cache: "no-store",
});

export const api = {
  items: () => fetch("/api/items", { cache: "no-store" }).then(j<Item[]>),
  importable: () => fetch("/api/items/importable", { cache: "no-store" }).then(j<Item[]>),
  item: (id: string) => fetch(`/api/items/${id}`, { cache: "no-store" }).then(j<Item>),
  addItem: (url: string) => fetch("/api/items", opts("POST", { url })).then(j<Item>),
  addMemo: (text: string) => fetch("/api/items", opts("POST", { text })).then(j<Item>),
  finishReading: (id: string) => fetch(`/api/items/${id}/read`, opts("POST")).then(j<Item>),
  updateItem: (id: string, patch: Partial<Item>) =>
    fetch(`/api/items/${id}`, opts("PATCH", patch)).then(j<Item>),
  deleteItem: (id: string) => fetch(`/api/items/${id}`, opts("DELETE")).then(j<{ ok: boolean }>),

  projects: () => fetch("/api/projects", { cache: "no-store" }).then(j<Project[]>),
  project: (id: string) =>
    fetch(`/api/projects/${id}`, { cache: "no-store" }).then(j<ProjectDetail>),
  addProject: (
    name: string,
    patch: { description?: string; tone?: "accent" | "neutral" } = {},
  ) => fetch("/api/projects", opts("POST", { name, ...patch })).then(j<Project>),
  updateProject: (
    id: string,
    patch: { name?: string; description?: string | null; tone?: "accent" | "neutral" },
  ) => fetch(`/api/projects/${id}`, opts("PATCH", patch)).then(j<Project>),
  deleteProject: (id: string) =>
    fetch(`/api/projects/${id}`, opts("DELETE")).then(j<{ ok: boolean }>),
  tags: () => fetch("/api/tags", { cache: "no-store" }).then(j<Tag[]>),

  notes: () => fetch("/api/notes", { cache: "no-store" }).then(j<Note[]>),
  note: (id: string) => fetch(`/api/notes/${id}`, { cache: "no-store" }).then(j<Note>),
  addNote: (
    input: {
      title?: string;
      projectId?: string;
      text?: string;
      body?: Note["body"];
      suggestions?: Note["suggestions"];
      tags?: Note["tags"];
      status?: Note["status"];
      sources?: Note["sources"];
    } = {},
  ) => fetch("/api/notes", opts("POST", input)).then(j<Note>),
  updateNote: (id: string, patch: Partial<Note>) =>
    fetch(`/api/notes/${id}`, opts("PATCH", patch)).then(j<Note>),
  deleteNote: (id: string) => fetch(`/api/notes/${id}`, opts("DELETE")).then(j<{ ok: boolean }>),
  appendParagraph: (id: string, text: string) =>
    fetch(`/api/notes/${id}`, opts("PATCH", { text })).then(j<Note>),
  suggestion: (id: string, suggestionId: string, action: "accept" | "dismiss") =>
    fetch(`/api/notes/${id}/suggestion`, opts("POST", { id: suggestionId, action })).then(j<Note>),

  compare: () => fetch("/api/compare", { cache: "no-store" }).then(j<CompareBoard>),
  rebuildCompare: (projectId?: string) =>
    fetch("/api/compare", opts("POST", projectId ? { projectId } : {})).then(j<CompareBoard>),


  export: (noteId: string, format: ExportFormat) =>
    fetch(`/api/export?noteId=${noteId}&format=${format}`, {
      cache: "no-store",
    }).then(j<ExportDraft>),
  runExport: (noteId: string, format: ExportFormat) =>
    fetch("/api/export", opts("POST", { noteId, format })).then(
      j<ExportDraft & { exportedTo: string }>
    ),
};

