/* ── Quill (bubble theme) note editor ─────────────────────────
   Overrides quill/dist/quill.bubble.css (imported in components/note-editor.tsx)
   for the Nocturne dark palette. Scoped to .note-editor for specificity. */
.note-editor .ql-container {
  font-family: inherit;
  font-size: 15px;
}
.note-editor .ql-editor {
  padding: 0;
  line-height: 1.85;
  color: color-mix(in srgb, var(--color-text) 90%, transparent);
  caret-color: var(--color-accent);
}
